import * as yaml from 'yaml'
import composeAppConfig from '../src/utils/ComposeAppConfig'
import { IDockerComposeService } from '../src/models/IOneClickAppModels'

describe('Compose app configuration', () => {
    test('map/list environments and short/long mounts and ports produce the same app config', () => {
        const short = yaml.parse(`
environment:
  TOKEN: a=b=c
  EMPTY: ""
  COUNT: 0
  ENABLED: "false"
volumes:
  - data:/data
  - /srv/files:/files
ports:
  - "8080:80"
  - "5353:53/udp"
`)
        const long = yaml.parse(`
environment:
  - TOKEN=a=b=c
  - EMPTY=
  - COUNT=0
  - ENABLED=false
volumes:
  - type: volume
    source: data
    target: /data
  - type: bind
    source: /srv/files
    target: /files
    read_only: false
ports:
  - target: 80
    published: "8080"
  - target: 53
    published: 5353
    protocol: udp
`)
        expect(composeAppConfig(short)).toEqual({
            envVars: [
                { key: 'TOKEN', value: 'a=b=c' },
                { key: 'EMPTY', value: '' },
                { key: 'COUNT', value: '0' },
                { key: 'ENABLED', value: 'false' },
            ],
            volumes: [
                { volumeName: 'data', containerPath: '/data' },
                { hostPath: '/srv/files', containerPath: '/files' },
            ],
            ports: [
                { hostPort: 8080, containerPort: 80 },
                { hostPort: 5353, containerPort: 53, protocol: 'udp' },
            ],
        })
        expect(composeAppConfig(long)).toEqual(composeAppConfig(short))
    })

    test('handles mixed entries and explicit port protocol and publishing mode', () => {
        expect(
            composeAppConfig({
                volumes: [
                    'data:/data:rw',
                    { type: 'bind', source: '/srv', target: '/srv' },
                ],
                ports: [
                    '8080:80/tcp',
                    {
                        published: 9000,
                        target: 90,
                        protocol: 'udp',
                        mode: 'host',
                    },
                ],
            })
        ).toMatchObject({
            volumes: [
                { volumeName: 'data', containerPath: '/data' },
                { hostPath: '/srv', containerPath: '/srv' },
            ],
            ports: [
                { hostPort: 8080, containerPort: 80, protocol: 'tcp' },
                {
                    hostPort: 9000,
                    containerPort: 90,
                    protocol: 'udp',
                    publishMode: 'host',
                },
            ],
        })
    })

    test('omits unresolved variables without reading the server environment', () => {
        process.env.CAPROVER_COMPOSE_TEST_SECRET = '[REDACTED]'
        try {
            expect(
                composeAppConfig({
                    environment: [
                        'CAPROVER_COMPOSE_TEST_SECRET',
                        'KEEP=',
                        'DUP=first',
                        'DUP=last',
                        'REMOVE=value',
                        'REMOVE',
                    ],
                }).envVars
            ).toEqual([
                { key: 'KEEP', value: '' },
                { key: 'DUP', value: 'last' },
            ])
            expect(
                composeAppConfig({
                    environment: {
                        CAPROVER_COMPOSE_TEST_SECRET: null,
                        ZERO: 0,
                        FALSE: false,
                    },
                }).envVars
            ).toEqual([
                { key: 'ZERO', value: '0' },
                { key: 'FALSE', value: 'false' },
            ])
        } finally {
            delete process.env.CAPROVER_COMPOSE_TEST_SECRET
        }
    })

    test.each([
        [{ environment: ['=secret'] }, 'environment'],
        [{ environment: [{ KEY: 'secret' }] }, 'environment'],
        [{ environment: { KEY: { nested: 'secret' } } }, 'environment'],
        [{ environment: 'KEY=secret' }, 'environment'],
        [{ volumes: { data: '/data' } }, 'volumes'],
        [{ volumes: ['/data'] }, 'volumes'],
        [{ volumes: ['./data:/data'] }, 'volumes'],
        [
            {
                volumes: [
                    {
                        type: 'volume',
                        source: 'data',
                        target: '/data',
                        read_only: true,
                    },
                ],
            },
            'read_only',
        ],
        [
            { volumes: [{ type: 'bind', source: './data', target: '/data' }] },
            'absolute bind',
        ],
        [{ volumes: [{ type: 'tmpfs', target: '/data' }] }, 'type'],
        [
            {
                volumes: [
                    {
                        type: 'volume',
                        source: 'data',
                        target: '/data',
                        volume: { nocopy: true },
                    },
                ],
            },
            'option volume',
        ],
        [{ ports: { 8080: 80 } }, 'ports'],
        [{ ports: ['127.0.0.1:8080:80'] }, 'host IPs'],
        [
            { ports: [{ published: 8080, target: 80, host_ip: '127.0.0.1' }] },
            'host_ip',
        ],
        [{ ports: ['8080-8082:80-82'] }, 'ranges'],
        [{ ports: [80] }, 'ports'],
        [{ ports: [{ target: 80 }] }, 'port numbers'],
        [{ ports: [{ published: '8080-8090', target: 80 }] }, 'port numbers'],
        [{ ports: [{ published: 8080, target: true }] }, 'port numbers'],
        [
            { ports: [{ published: 8080, target: 80, protocol: 'sctp' }] },
            'protocol',
        ],
        [{ ports: [{ published: 8080, target: 80, mode: 'invalid' }] }, 'mode'],
        [{ ports: ['0:80'] }, 'port numbers'],
        [{ ports: ['65535:80'] }, 'port numbers'],
    ])('rejects unsupported or malformed config %j', (service, message) => {
        expect(() =>
            composeAppConfig(service as IDockerComposeService)
        ).toThrow(message)
    })

    test.each(['ro', 'rw', 'z', 'ro,z'])(
        'preserves legacy short mount suffix behavior: %s',
        (suffix) => {
            expect(
                composeAppConfig({
                    volumes: [`data:/data:${suffix}`, `/srv:/files:${suffix}`],
                }).volumes
            ).toEqual([
                { volumeName: 'data', containerPath: '/data' },
                { hostPath: '/srv', containerPath: '/files' },
            ])
        }
    )

    test.each([
        ['__proto__=value', 'constructor=other'],
        JSON.parse('{"__proto__":"value","constructor":"other"}'),
    ])('preserves special environment names as data: %j', (environment) => {
        expect(composeAppConfig({ environment }).envVars).toEqual([
            { key: '__proto__', value: 'value' },
            { key: 'constructor', value: 'other' },
        ])
    })

    test('preserves the input service and unrelated fields', () => {
        const service: IDockerComposeService = {
            image: 'nginx',
            environment: ['TOKEN=a=b', 'EMPTY='],
            volumes: [
                'data:/data',
                { type: 'bind', source: '/srv', target: '/srv' },
            ],
            ports: [
                '8080:80',
                { published: 9000, target: 90, protocol: 'udp', mode: 'host' },
            ],
            command: ['run', '--verbose'],
            depends_on: ['db'],
            hostname: 'example',
        }
        const snapshot = JSON.stringify(service)
        const first = composeAppConfig(service)
        expect(JSON.stringify(service)).toBe(snapshot)
        expect(composeAppConfig(service)).toEqual(first)
    })

    test.each([
        [{ environment: ['OK=value', '=secret'] }, 'environment[1]'],
        [{ environment: { TOKEN: ['secret'] } }, 'environment.TOKEN'],
        [
            {
                volumes: [
                    'data:/data',
                    {
                        type: 'volume',
                        source: 'cache',
                        target: '/cache',
                        read_only: true,
                    },
                ],
            },
            'volumes[1].read_only',
        ],
        [{ volumes: [{ type: 'tmpfs', target: '/tmp' }] }, 'volumes[0].type'],
        [
            { volumes: [{ type: 'volume', target: '/data' }] },
            'volumes[0].source',
        ],
        [
            {
                volumes: [
                    { type: 'volume', source: 'data', target: 'relative' },
                ],
            },
            'volumes[0].target',
        ],
        [{ volumes: [[]] }, 'volumes[0]'],
        [
            {
                ports: [
                    '8080:80',
                    { target: 80, published: 9000, host_ip: '127.0.0.1' },
                ],
            },
            'ports[1].host_ip',
        ],
        [{ ports: [{ published: 8080, target: 0 }] }, 'ports[0].target'],
        [{ ports: [{ published: 'bad', target: 80 }] }, 'ports[0].published'],
        [
            { ports: [{ published: 8080, target: 80, protocol: 'bad' }] },
            'ports[0].protocol',
        ],
        [
            { ports: [{ published: 8080, target: 80, mode: 'bad' }] },
            'ports[0].mode',
        ],
        [{ ports: [[]] }, 'ports[0]'],
    ])('reports the exact invalid field: %j', (service, path) => {
        expect(() =>
            composeAppConfig(service as IDockerComposeService, 'services.app')
        ).toThrow(`services.app.${path}:`)
    })
})

import {
    DockerBuildOutputDecoder,
    DockerJsonStreamParser,
} from '../src/docker/DockerBuildOutput'

function varint(value: number): Buffer {
    const bytes: number[] = []
    do {
        const remaining = Math.floor(value / 128)
        bytes.push(value % 128 | (remaining ? 0x80 : 0))
        value = remaining
    } while (value)
    return Buffer.from(bytes)
}

function bytesField(fieldNumber: number, value: string | Buffer): Buffer {
    const data = Buffer.isBuffer(value) ? value : Buffer.from(value)
    return Buffer.concat([
        varint(fieldNumber * 8 + 2),
        varint(data.length),
        data,
    ])
}

test('buffers split JSON messages and parses multiple messages', () => {
    const parser = new DockerJsonStreamParser()

    expect(parser.push('{"stream":"hel')).toEqual([])
    expect(parser.push('lo"}\n{"error":"failed"}\n')).toEqual([
        { stream: 'hello' },
        { error: 'failed' },
    ])
})

test('keeps buffers isolated and flushes the final message', () => {
    const first = new DockerJsonStreamParser()
    const second = new DockerJsonStreamParser()

    first.push('{"stream":"first"')
    second.push('{"stream":"second"}')

    expect(first.push('}\n')).toEqual([{ stream: 'first' }])
    expect(second.flush()).toEqual([{ stream: 'second' }])
})

test('reports malformed JSON without interrupting later messages', () => {
    const parser = new DockerJsonStreamParser()

    expect(parser.push('not-json\n{"stream":"still running"}\n')).toEqual([
        { stream: 'Cannot parse not-json' },
        { stream: 'still running' },
    ])
})

test('preserves traditional builder output', () => {
    const decoder = new DockerBuildOutputDecoder()
    const message = { stream: 'Step 1/1\n' }

    expect(decoder.decode(message)).toEqual([message])
})

test('decodes BuildKit vertices, logs, and warnings', () => {
    const vertex = Buffer.concat([
        bytesField(1, 'sha256:vertex'),
        bytesField(3, '[1/1] RUN npm test'),
    ])
    const log = Buffer.concat([
        bytesField(1, 'sha256:vertex'),
        bytesField(4, 'tests passed\n'),
    ])
    const warning = bytesField(3, 'deprecated instruction')
    const status = Buffer.concat([
        bytesField(1, vertex),
        bytesField(3, log),
        bytesField(4, warning),
    ])
    const decoder = new DockerBuildOutputDecoder()

    expect(
        decoder.decode({
            id: 'moby.buildkit.trace',
            aux: status.toString('base64'),
        })
    ).toEqual([
        { stream: '[1/1] RUN npm test\n' },
        { stream: 'tests passed\n' },
        { stream: 'WARNING: deprecated instruction\n' },
    ])

    expect(
        decoder.decode({
            id: 'moby.buildkit.trace',
            aux: bytesField(1, vertex).toString('base64'),
        })
    ).toEqual([])
})

test('decodes BuildKit vertex errors once with error details', () => {
    const vertex = Buffer.concat([
        bytesField(1, 'sha256:failed-vertex'),
        bytesField(3, '[1/1] RUN exit 1'),
        bytesField(7, 'process exited with code 1'),
    ])
    const message = {
        id: 'moby.buildkit.trace',
        aux: bytesField(1, vertex).toString('base64'),
    }
    const decoder = new DockerBuildOutputDecoder()

    expect(decoder.decode(message)).toEqual([
        { stream: '[1/1] RUN exit 1\n' },
        {
            error: 'process exited with code 1',
            errorDetail: { message: 'process exited with code 1' },
        },
    ])
    expect(decoder.decode(message)).toEqual([])
})

test('reports malformed BuildKit protobuf output', () => {
    const decoder = new DockerBuildOutputDecoder()

    expect(
        decoder.decode({
            id: 'moby.buildkit.trace',
            aux: Buffer.from([0x0a, 0x05, 0x01]).toString('base64'),
        })
    ).toEqual([{ stream: 'Cannot parse BuildKit build output\n' }])
})

test('ignores unrelated aux messages', () => {
    const decoder = new DockerBuildOutputDecoder()

    expect(
        decoder.decode({ id: 'other.message', aux: 'not-protobuf' })
    ).toEqual([])
})

test('skips 10-byte protobuf varints without dropping later output', () => {
    const fullWidthVarint = Buffer.from([
        0xff, 0xff, 0xff, 0xff, 0xff, 0xff, 0xff, 0xff, 0xff, 0x01,
    ])
    const log = Buffer.concat([
        Buffer.from([0x08]),
        fullWidthVarint,
        bytesField(4, 'still visible\n'),
    ])
    const status = bytesField(3, log)
    const decoder = new DockerBuildOutputDecoder()

    expect(
        decoder.decode({
            id: 'moby.buildkit.trace',
            aux: status.toString('base64'),
        })
    ).toEqual([{ stream: 'still visible\n' }])
})

import AppsDataStore from '../src/datastore/AppsDataStore'
import OneClickAppDeploymentHelper from '../src/user/oneclick/OneClickAppDeploymentHelper'
import OneClickAppDeployManager, {
    ONE_CLICK_APP_NAME_VAR_NAME,
} from '../src/user/oneclick/OneClickAppDeployManager'
import { IOneClickTemplate } from '../src/models/IOneClickAppModels'

describe('OneClickAppDeployManager', () => {
    test('treats omitted values as an empty array', () => {
        const onDeploymentStateChanged = jest.fn()
        const manager = new OneClickAppDeployManager(
            {} as any,
            {} as any,
            onDeploymentStateChanged
        )

        const template: IOneClickTemplate = {
            captainVersion: 4,
            services: {},
            caproverOneClickApp: {
                displayName: 'Test App',
                instructions: {
                    start: '',
                    end: '',
                },
                variables: [
                    {
                        id: ONE_CLICK_APP_NAME_VAR_NAME,
                        label: 'App Name',
                    },
                ],
            },
        }

        expect(() => manager.startDeployProcess(template)).not.toThrow()
        expect(onDeploymentStateChanged).toHaveBeenCalledWith({
            steps: ['Parsing the template'],
            error: 'App name ($$cap_appname) is required.',
            currentStep: 0,
        })
    })

    describe('checks every app name before it creates anything', () => {
        const template: IOneClickTemplate = {
            captainVersion: 4,
            services: {
                [ONE_CLICK_APP_NAME_VAR_NAME]: { image: 'nginx' },
                [`${ONE_CLICK_APP_NAME_VAR_NAME}-worker`]: { image: 'nginx' },
            },
            caproverOneClickApp: {
                displayName: 'Test App',
                instructions: { start: '', end: 'done' },
                variables: [
                    { id: ONE_CLICK_APP_NAME_VAR_NAME, label: 'App Name' },
                ],
            },
        }

        // The steps that create something; each one only records its call.
