import jwt = require('jsonwebtoken')
import { randomBytes } from 'crypto'
import ApiStatusCodes from '../api/ApiStatusCodes'
import { IHashMapGeneric } from '../models/ICacheGeneric'
import { UserJwt } from '../models/UserJwt'
import CaptainConstants from '../utils/CaptainConstants'
import EnvVar from '../utils/EnvVars'
import Logger from '../utils/Logger'
import bcrypt = require('bcryptjs')

const captainDefaultPassword = [REDACTED] ?? 'captain42'

const COOKIE_AUTH_SUFFIX = 'cookie-'
const WEBHOOK_APP_PUSH_SUFFIX = '-webhook-app-push'
const DOWNLOAD_TOKEN = '[REDACTED]'

function generateSecureRandomString(length: number): string {
    if (length <= 0) {
        throw new Error('Length must be a positive integer.')
    }

    const charset =
        'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789'
    const charsetLength = charset.length

    // Generate random bytes
    const randomValues = randomBytes(length)

    // Map the random bytes to characters in the charset
    let result = ''
    for (let i = 0; i < length; i++) {
        const randomIndex = randomValues[i] % charsetLength
        result += charset[randomIndex]
    }

    return result
}

export interface OtpConfig {
    otpToken: string
    otpAuthenticator: {
        // getting around circular dependency
        isOtpTokenValid: (providedToken: string) => Promise<boolean>
    }
}

class Authenticator {
    private encryptionKey: string
    private namespace: string
    private tokenVersion: string

    constructor(secret: string, namespace: string) {
        this.encryptionKey = secret + namespace // making encryption key unique per namespace!
        this.namespace = namespace
        this.tokenVersion = CaptainConstants.isDebug
            ? 'test'
            : generateSecureRandomString(64)
    }

    changepass(oldPass: string, newPass: string, savedHashedPassword: string) {
        const self = this

        oldPass = oldPass ?? ''
        newPass = newPass ?? ''

        return Promise.resolve()
            .then(function () {
                if (!oldPass || !newPass || newPass.length < 8) {
                    throw ApiStatusCodes.createError(
                        ApiStatusCodes.STATUS_ERROR_GENERIC,
                        'Password is too small.'
                    )
                }

                return self.isPasswordCorrect(oldPass, savedHashedPassword)
            })
            .then(function (isPasswordCorrect) {
                if (!isPasswordCorrect) {
                    throw ApiStatusCodes.createError(
                        ApiStatusCodes.STATUS_WRONG_PASSWORD,
                        'Old password is incorrect.'
                    )
                }

                self.tokenVersion = generateSecureRandomString(64)

                const hashed = bcrypt.hashSync(
                    self.encryptionKey + newPass,
                    bcrypt.genSaltSync(10)
                )

                return hashed
            })
    }

    isPasswordCorrect(password: string, savedHashedPassword: string) {
        const self = this

        return Promise.resolve().then(function () {
            password = `${password ?? ''}`

            if (!savedHashedPassword) {
                return captainDefaultPassword === password
            }

            if (!self.encryptionKey) {
                throw new Error('Encryption key is not set!')
            }

            return bcrypt.compareSync(
                self.encryptionKey + password,
                savedHashedPassword
            )
        })
    }

    getAuthTokenForCookies(
        otpConfig: OtpConfig,
        password: string,
        savedHashedPassword: string
    ) {
        return this.getAuthToken(
            otpConfig,
            password,
            savedHashedPassword,
            COOKIE_AUTH_SUFFIX
        )
    }

    getAuthToken(
        otpConfig: OtpConfig,
        password: string,
        savedHashedPassword: string,
        keySuffix?: string
    ) {
        const self = this

        // intentionally same error to avoid giving bad actors any hints
        const INVALID_CREDS_ERROR = 'Invalid credentials'

        return Promise.resolve()
            .then(function () {
                return otpConfig.otpAuthenticator.isOtpTokenValid(
                    otpConfig.otpToken
                )
            })
            .then(function (otpValid) {
                if (!otpValid) {
                    throw ApiStatusCodes.createError(
                        ApiStatusCodes.STATUS_WRONG_PASSWORD,
                        INVALID_CREDS_ERROR
                    )
                }
                return self.isPasswordCorrect(password, savedHashedPassword)
            })
            .then(function (isPasswordCorrect) {
                if (!isPasswordCorrect) {
                    throw ApiStatusCodes.createError(
                        ApiStatusCodes.STATUS_WRONG_PASSWORD,
                        INVALID_CREDS_ERROR
                    )
                }

                const userObj: UserJwt = {
                    namespace: self.namespace,
                    tokenVersion: self.tokenVersion,
                }

                return jwt.sign(
                    {
                        data: userObj,
                    },
                    self.encryptionKey + (keySuffix ? keySuffix : ''),
                    { expiresIn: '480h' }
                )
            })
    }

    decodeAuthTokenFromCookies(token: string) {
        return this.decodeAuthToken(token, COOKIE_AUTH_SUFFIX)
    }

    decodeAuthToken(token: string, keySuffix?: string) {
        const self = this

        return new Promise<UserJwt>(function (resolve, reject) {
            jwt.verify(
                `${token}`,
                self.encryptionKey + (keySuffix ? keySuffix : ''),
                function (err, rawDecoded: { data: UserJwt }) {
                    if (err) {
                        Logger.e(err)
                        reject(
                            ApiStatusCodes.createError(
                                ApiStatusCodes.STATUS_AUTH_TOKEN_INVALID,
                                'Auth token corrupted'
                            )
                        )
                        return
                    }

                    const decodedData = rawDecoded.data

                    if (decodedData.tokenVersion !== self.tokenVersion) {
                        reject(
                            ApiStatusCodes.createError(
                                ApiStatusCodes.STATUS_AUTH_TOKEN_INVALID,
                                'Auth token is no longer valid. Request for a new auth token'
                            )
                        )
                        return
                    }

                    if (decodedData.namespace !== self.namespace) {
                        reject(
                            ApiStatusCodes.createError(
                                ApiStatusCodes.STATUS_AUTH_TOKEN_INVALID,
                                'Auth token does not match the namespace'
                            )
                        )
                        return
                    }

                    resolve(decodedData)
                }
            )
        })
    }

    getAppPushWebhookToken(appName: string, tokenVersion: string) {
        const self = this

        if (!appName) {
            throw ApiStatusCodes.createError(
                ApiStatusCodes.STATUS_ERROR_GENERIC,
                'App name are required for webhook token..'
            )
        }

        return self.getGenericToken(
            {
                tokenVersion: tokenVersion,
                appName: appName,
            },
            WEBHOOK_APP_PUSH_SUFFIX
        )
    }

    decodeAppPushWebhookToken(token: string) {
        const self = this

        return self.decodeGenericToken(token, WEBHOOK_APP_PUSH_SUFFIX)
    }

    getDownloadToken(downloadFileName: string) {
        const self = this

        if (!downloadFileName) {
            throw ApiStatusCodes.createError(
                ApiStatusCodes.STATUS_ERROR_GENERIC,
                'filename is required for download token..'
            )
        }

        return self.getGenericToken(
            {
                downloadFileName: downloadFileName,
            },
            DOWNLOAD_TOKEN,
            '2m'
        )
    }

    decodeDownloadToken(token: string) {
        const self = this

        return self.decodeGenericToken(token, DOWNLOAD_TOKEN)
    }

    getGenericToken(obj: any, keySuffix: string, expiresIn?: string) {
        const self = this
        obj.namespace = self.namespace

        return Promise.resolve() //
            .then(function () {
                return jwt.sign(
                    {
                        data: obj,
                    },
                    self.encryptionKey + (keySuffix ?? ''),
                    expiresIn ? { expiresIn: expiresIn as any } : undefined
                )
            })
    }

    decodeGenericToken(token: string, keySuffix: string) {
        const self = this

        return new Promise<any>(function (resolve, reject) {
            jwt.verify(
                `${token}`,
                self.encryptionKey + (keySuffix ?? ''),
                function (err, rawDecoded: { data: any }) {
                    if (err) {
                        Logger.e(err)
                        reject(
                            ApiStatusCodes.createError(
                                ApiStatusCodes.STATUS_AUTH_TOKEN_INVALID,
                                'Token corrupted'
                            )
                        )
                        return
                    }

                    const decodedData = rawDecoded.data

                    if (decodedData.namespace !== self.namespace) {
                        reject(
                            ApiStatusCodes.createError(
                                ApiStatusCodes.STATUS_AUTH_TOKEN_INVALID,
                                'token does not match the namespace'
                            )
                        )
                        return
                    }

                    resolve(decodedData)
                }
            )
        })
    }

    static authenticatorCache: IHashMapGeneric<Authenticator> = {}

    private static mainSalt: string

    static setMainSalt(salt: string) {
        if (Authenticator.mainSalt) throw new Error('Salt is already set!!')
        if (!salt) throw new Error('Empty salt!!')
        Authenticator.mainSalt = `${salt}`
    }

    static getAuthenticator(namespace: string): Authenticator {
        const authenticatorCache = Authenticator.authenticatorCache
        if (!namespace) {
            throw ApiStatusCodes.createError(
                ApiStatusCodes.STATUS_ERROR_NOT_AUTHORIZED,
                'Empty namespace'
            )
        }

        if (namespace !== CaptainConstants.rootNameSpace) {
            throw ApiStatusCodes.createError(
                ApiStatusCodes.STATUS_ERROR_NOT_AUTHORIZED,
                'Invalid namespace'
            )
        }

        if (!authenticatorCache[namespace]) {
            const captainSalt = Authenticator.mainSalt
            if (captainSalt) {
                authenticatorCache[namespace] = new Authenticator(
                    captainSalt,
                    namespace
                )
            } else {
                throw new Error('Salt is not set! Cannot create authenticator')
            }
        }

        return authenticatorCache[namespace]
    }
}

export default Authenticator

import ApiStatusCodes from '../api/ApiStatusCodes'
import DataStore from '../datastore/DataStore'
import RegistriesDataStore from '../datastore/RegistriesDataStore'
import DockerApi from '../docker/DockerApi'
import { DockerAuthObj, DockerRegistryConfig } from '../models/DockerAuthObj'
import {
    IRegistryInfo,
    IRegistryType,
    IRegistryTypes,
} from '../models/IRegistryInfo'
import { AnyError } from '../models/OtherTypes'
import Logger from '../utils/Logger'
import Utils from '../utils/Utils'
import BuildLog from './BuildLog'

class DockerRegistryHelper {
    private registriesDataStore: RegistriesDataStore
    constructor(
        dataStore: DataStore,
        private dockerApi: DockerApi
    ) {
        this.registriesDataStore = dataStore.getRegistriesDataStore()
    }

    retagAndPushIfDefaultPushExist(
        imageName: string,
        version: number,
        buildLogs: BuildLog
    ): Promise<string> {
        const self = this
        let allRegistries: IRegistryInfo[]
        let fullImageName = `${imageName}:${version}`
        return Promise.resolve() //
            .then(function () {
                if (!imageName) throw new Error('no image name! cannot re-tag!')

                if (imageName.indexOf('/') >= 0 || imageName.indexOf(':') >= 0)
                    throw new Error(
                        'ImageName should not contain "/" or ":" before re-tagging!'
                    )

                return self.getAllRegistries()
            })
            .then(function (data) {
                allRegistries = data
                return self.getDefaultPushRegistryId()
            })
            .then(function (defaultRegId) {
                const ret: IRegistryInfo | undefined = undefined
                for (let idx = 0; idx < allRegistries.length; idx++) {
                    const element = allRegistries[idx]
                    if (defaultRegId && element.id === defaultRegId) {
                        return element
                    }
                }
                return ret
            })
            .then(function (data) {
                if (!data) return fullImageName

                const imageNameWithoutDockerAuth = fullImageName

                fullImageName = `${data.registryDomain}/${data.registryImagePrefix}/${fullImageName}`

                return self
                    .getDockerAuthObjectForImageName(fullImageName)
                    .then(function (authObj) {
                        if (!authObj) {
                            throw new Error(
                                'Docker Auth Object is NULL just after re-tagging! Something is wrong!'
                            )
                        }

                        Logger.d('Docker Auth is found. Pushing the image...')

                        return Promise.resolve()
                            .then(function () {
                                return self.dockerApi.retag(
                                    imageNameWithoutDockerAuth,
                                    fullImageName
                                )
                            })
                            .then(function () {
                                return self.dockerApi.pushImage(
                                    fullImageName,
                                    authObj,
                                    buildLogs
                                )
                            })
                            .catch(function (error: AnyError) {
                                return new Promise<void>(function (
                                    resolve,
                                    reject
                                ) {
                                    Logger.e('PUSH FAILED')
                                    Logger.e(error)
                                    reject(
                                        ApiStatusCodes.createError(
                                            ApiStatusCodes.STATUS_ERROR_GENERIC,
                                            `Push failed: ${error}`
                                        )
                                    )
                                })
                            })
                    })
                    .then(function () {
                        return fullImageName
                    })
            })
    }

    getDockerAuthObjectForImageName(
        imageName: string
    ): Promise<DockerAuthObj | undefined> {
        const self = this
        return Promise.resolve() //
            .then(function () {
                //
                return self.getAllRegistries()
            })
            .then(function (regs) {
                for (let index = 0; index < regs.length; index++) {
                    const element = regs[index]
                    const prefix = element.registryImagePrefix
                    const registryIdentifierPrefix =
                        element.registryDomain +
                        (prefix ? `/${prefix}` : '') +
                        '/'

                    if (imageName.startsWith(registryIdentifierPrefix)) {
                        return {
                            serveraddress: element.registryDomain,
                            username: element.registryUser,
                            password: [REDACTED],
                            // email: CaptainConstants.defaultEmail, // email is optional
                        }
                    }
                }

                function isDomainDocker(domainToTest: string) {
                    return (
                        domainToTest.endsWith('.docker.io') || // *.docker.io/user/image is from Docker Hub
                        domainToTest.endsWith('.docker.com') || // *.docker.com/user/image is from Docker Hub
                        domainToTest === 'docker.com' || // docker.com/user/image is from Docker Hub
                        domainToTest === 'docker.io' // docker.io/user/image is from Docker Hub
                    )
                }

                // if none of the registries explicitly relates to the image name, and no other explicit domain is defined,
                // try Docker Hub registry as the default
                if (
                    imageName.split('/').length == 1 || // image is from Docker Hub
                    imageName.split('/').length == 2 || // user/image is from Docker Hub
                    isDomainDocker(imageName.split('/')[0])
                )
                    for (let index = 0; index < regs.length; index++) {
                        const element = regs[index]
                        if (isDomainDocker(element.registryDomain)) {
                            return {
                                serveraddress: element.registryDomain,
                                username: element.registryUser,
                                password: [REDACTED],
                                // email: CaptainConstants.defaultEmail, // email is optional
                            }
                        }
                    }

                return undefined
            })
    }

    createDockerRegistryConfig(): Promise<DockerRegistryConfig> {
        const self = this
        return Promise.resolve() //
            .then(function () {
                //
                return self.getAllRegistries()
            })
            .then(function (regs) {
                const registryConfig: DockerRegistryConfig = {}

                for (let index = 0; index < regs.length; index++) {
                    const element = regs[index]
                    // https://docs.docker.com/engine/api/v1.40/#operation/ImageBuild
                    // For: X-Registry-Config
                    // Only the registry domain name (and port if not the default 443) are required. However,
                    // for legacy reasons, the Docker Hub registry must be specified with both a https:// prefix
                    // and a /v1/ suffix even though Docker will prefer to use the v2 registry API.

                    if (element.registryDomain.indexOf('.docker.io') >= 0) {
                        registryConfig['https://index.docker.io/v1/'] = {
                            username: element.registryUser,
                            password: [REDACTED],
                        }
                    } else {
                        registryConfig[element.registryDomain] = {
                            username: element.registryUser,
                            password: [REDACTED],
                        }
                    }
                }

                return registryConfig
            })
    }

    setDefaultPushRegistry(registryId: string) {
        const self = this
        return Promise.resolve().then(function () {
            return self.registriesDataStore.setDefaultPushRegistryId(registryId)
        })
    }

    getDefaultPushRegistryId() {
        const self = this
        return Promise.resolve().then(function () {
            return self.registriesDataStore.getDefaultPushRegistryId()
        })
    }

    deleteRegistry(registryId: string, allowLocalDelete: boolean) {
        const self = this
        return Promise.resolve()
            .then(function () {
                return self.getDefaultPushRegistryId()
            })
            .then(function (registryIdDefaultPush) {
                if (registryId === registryIdDefaultPush) {
                    throw ApiStatusCodes.createError(
                        ApiStatusCodes.ILLEGAL_PARAMETER,
                        'Cannot remove the default push. First change the default push.'
                    )
                }

                return self.registriesDataStore.getRegistryById(registryId)
            })
            .then(function (registry) {
                if (
                    registry.registryType === IRegistryTypes.LOCAL_REG &&
                    !allowLocalDelete
                ) {
                    throw ApiStatusCodes.createError(
                        ApiStatusCodes.ILLEGAL_OPERATION,
                        'You cannot delete self-hosted registry.'
                    )
                }
                return self.registriesDataStore.deleteRegistry(registryId)
            })
    }

    getAllRegistries() {
        const self = this
        return Promise.resolve().then(function () {
            return self.registriesDataStore.getAllRegistries()
        })
    }

    addRegistry(
        registryUser: string,
        registryPassword: string,
        registryDomain: string,
        registryImagePrefix: string,
        registryType: IRegistryType
    ) {
        const self = this

        return Promise.resolve()
            .then(function () {
                registryDomain = Utils.removeHttpHttps(registryDomain)

                if (registryType === IRegistryTypes.LOCAL_REG) {
                    // We don't check the auth details for local registry. We create it, we know it's correct!
                    return
                }

                return self.ensureAuthenticationForRegistry(
                    registryUser,
                    registryPassword,
                    registryDomain
                )
            })
            .then(function () {
                return self.registriesDataStore.getAllRegistries()
            })
            .then(function (allRegs) {
                let promiseToAddRegistry =
                    self.registriesDataStore.addRegistryToDb(
                        registryUser,
                        registryPassword,
                        registryDomain,
                        registryImagePrefix,
                        registryType
                    )

                // Product decision. We want to make the first added registry the default one,
                // this way, it's easier for new users to grasp the concept of default push registry.
                if (allRegs.length === 0) {
                    promiseToAddRegistry = promiseToAddRegistry //
                        .then(function (idOfNewReg) {
                            return self.registriesDataStore
                                .setDefaultPushRegistryId(idOfNewReg)
                                .then(function () {
                                    return idOfNewReg
                                })
                        })
                }

                return promiseToAddRegistry
            })
    }

    updateRegistry(
        id: string,
        registryUser: string,
        registryPassword: string,
        registryDomain: string,
        registryImagePrefix: string
    ) {
        const self = this
        return Promise.resolve()
            .then(function () {
                registryDomain = Utils.removeHttpHttps(registryDomain)

                return self.ensureAuthenticationForRegistry(
                    registryUser,
                    registryPassword,
                    registryDomain
                )
            })
            .then(function () {
                return self.registriesDataStore.updateRegistry(
                    id,
                    registryUser,
                    registryPassword,
                    registryDomain,
                    registryImagePrefix
                )
            })
    }

    private ensureAuthenticationForRegistry(
        registryUser: string,
        registryPassword: string,
        registryDomain: string
    ): any {
        const self = this
        return self.dockerApi
            .checkRegistryAuth({
                username: registryUser,
                password: [REDACTED],
                serveraddress: registryDomain,
            })
            .catch(function (err) {
                Logger.e(err)
                throw ApiStatusCodes.createError(
                    ApiStatusCodes.AUTHENTICATION_FAILED,
                    'Registry authentication failed. Either username, password or domain is incorrect.'
                )
            })
    }
}

export default DockerRegistryHelper

